// HomeScreen.js - главный экран приложения
import React, { useState } from 'react';
import {
  View,
  Text,
  TouchableOpacity,
  StyleSheet,
  ScrollView,
  ActivityIndicator,
  Alert
} from 'react-native';
import useStorage from '../hooks/useStorage';
import useApi from '../hooks/useApi';
import { apiService } from '../services/apiService';

const HomeScreen = ({ navigation }) => {
  // Логика оставлена (по ТЗ), но UI скрыт
  const { value: count, setValue: setCount, loading: storageLoading } = useStorage('counter', 0);
  const { data: users, loading: apiLoading, error: apiError, refetch } = useApi(
      'https://jsonplaceholder.typicode.com/users'
  );

  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  const addLocalItem = () => {
    const newItem = {
      id: Date.now(),
      title: `Элемент ${localData.length + 1}`,
      timestamp: new Date().toLocaleTimeString()
    };
    setLocalData(prev => [newItem, ...prev]);
  };

  const createPost = async () => {
    setPostLoading(true);
    try {
      const newPost = {
        title: 'Новый пост',
        body: 'Это тестовый пост',
        userId: 1
      };

      await new Promise(resolve => setTimeout(resolve, 1000));
      const result = await apiService.createPost(newPost);

      Alert.alert('Успех', 'Пост создан!');
    } catch (error) {
      Alert.alert('Ошибка', 'Не удалось создать пост');
    } finally {
      setPostLoading(false);
    }
  };

  const resetAll = () => {
    setCount(0);
    setLocalData([]);
  };

  if (storageLoading) {
    return (
        <View style={styles.center}>
          <ActivityIndicator size="large" color="#007AFF" />
          <Text>Загрузка...</Text>
        </View>
    );
  }

  return (
      <ScrollView style={styles.container}>
        {/* Навигация — единственный отображаемый блок */}
        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Навигация</Text>

          <View style={styles.navRow}>
            <TouchableOpacity
                style={styles.navButton}
                onPress={() => navigation.navigate('Media')}
            >
              <Text style={styles.navButtonText}>Мультимедиа</Text>
            </TouchableOpacity>

            <TouchableOpacity
                style={styles.navButton}
                onPress={() => navigation.navigate('Gallery')}
            >
              <Text style={styles.navButtonText}>Галерея</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.navRow}>
            <TouchableOpacity
                style={styles.navButton}
                onPress={() => navigation.navigate('Analytics')}
            >
              <Text style={styles.navButtonText}>Аналитика</Text>
            </TouchableOpacity>

            <TouchableOpacity
                style={styles.navButton}
                onPress={() => navigation.navigate('Settings')}
            >
              <Text style={styles.navButtonText}>Настройки</Text>
            </TouchableOpacity>
          </View>
        </View>

        {/* Блок СЧЁТЧИКА — скрыт */}
        {false && <View></View>}

        {/* Блок ЛОКАЛЬНЫХ ДАННЫХ — скрыт */}
        {false && <View></View>}

        {/* Блок API — скрыт */}
        {false && <View></View>}
      </ScrollView>
  );
};

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#f5f5f5',
    padding: 20,
  },
  center: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  section: {
    backgroundColor: 'white',
    padding: 15,
    borderRadius: 10,
    marginBottom: 15,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.1,
    shadowRadius: 4,
    elevation: 3,
  },
  sectionTitle: {
    fontSize: 20,
    fontWeight: 'bold',
    marginBottom: 10,
    color: '#333',
  },
  navRow: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    marginBottom: 10,
  },
  navButton: {
    backgroundColor: '#34C759',
    paddingHorizontal: 20,
    paddingVertical: 15,
    borderRadius: 8,
    alignItems: 'center',
    flex: 1,
    marginHorizontal: 5,
  },
  navButtonText: {
    color: 'white',
    fontSize: 16,
    fontWeight: '600',
  },
});

export default HomeScreen;
